(() => {
  const Z=window.Zucco,{state,platform:P,ui:U,ROUTES:R,escape:E,icon:I,avatar:A,badge:B,btn:BT,money:M}=Z;
  const studentSet=()=>P.students.filter(s=>U.match('students',s.name,s.phone,s.code)&&(P.studentStatus===undefined||P.studentStatus==='all'||s.status===P.studentStatus));
  const studentRows=()=>studentSet().slice((P.studentPage-1)*8,P.studentPage*8).map(s=>`<tr><td><div class="row gap-12">${A(s.name,s.id==='s1'?'':'slate')}<div>${U.link(s.name,'ext-open-student:'+s.id)}<p class="table-secondary mono">#${s.code}</p></div></div></td><td class="mono caption">${E(s.phone)}</td><td>${B(s.group)}</td><td>${U.status(s.status)}</td><td class="mono ${Z.studentBalance(s)<0?'text-danger':'text-success'}">${Z.signedMoney(Z.studentBalance(s))}</td><td><span class="coin-balance">${I('coin')}${Z.studentCoins(s)}</span></td><td>${BT('View profile','ext-open-student:'+s.id,'chevron','small ghost')}</td></tr>`).join('');
  Z.listRenderers.students=studentRows;
  Z.renderers[R.STUDENTS]=()=>Z.heading('Students','A complete view of every learner, group, and balance.',BT('Export students','ext-export-students','download')+BT('Add student','ext-new-student','plus','primary'))+
    U.metrics([['Total students',P.students.length,'Across all sample student records','users'],['Active',P.students.filter(s=>s.status==='Active').length,'Currently attending classes','checkCircle','success'],['Trial students',P.students.filter(s=>s.status==='Trial').length,'Getting to know the academy','calendar'],['Outstanding balance',P.students.filter(s=>Z.studentBalance(s)<0).length,'Students with unpaid tuition','wallet','danger']])+
    U.toolbar('students','Search name, phone, or student ID…',`<select class="select" data-extra-filter="students-status" aria-label="Student status"><option value="all">All statuses</option>${['Active','Trial','Frozen','Debtor','Completed'].map(v=>`<option ${P.studentStatus===v?'selected':''}>${v}</option>`).join('')}</select>`)+
    U.table([['Student',25],['Phone',19],['Group',11],['Status',12],['Balance, UZS',14],['Coins',8],['',11]],studentRows(),'students',`<span>Page ${P.studentPage} · ${studentSet().length} matching students</span><div class="pagination">${BT('Previous','ext-student-page:-1','left','small')}<span class="page-number mono">${P.studentPage}</span>${BT('Next','ext-student-page:1','chevron','small')}</div>`);
  const courseCards=()=>P.courses.filter(c=>U.match('courses',c.name,c.subject,c.level)).map(c=>`<article class="panel course-card" data-component="CourseCard"><div class="course-card-top"><span class="course-symbol">${I(c.icon)}</span>${U.status(c.status)}</div><div><h2>${E(c.name)}</h2><p class="table-secondary">${E(c.subject)} · ${E(c.level)}</p></div><p class="description">${E(c.description)}</p><div class="course-facts"><div><strong>${c.months} months</strong><span>Duration</span></div><div><strong>${c.lessons} / month</strong><span>Lessons</span></div><div><strong>${c.groups} groups</strong><span>Running</span></div></div><div class="course-card-bottom"><strong class="mono">${M(c.price)}<small> UZS / mo</small></strong>${BT('View course','ext-open-course:'+c.id,'chevron','small')}</div></article>`).join('');
  Z.listRenderers.courses=courseCards;
  Z.renderers[R.COURSES]=()=>Z.heading('Courses','Shape clear learning paths for every level and ambition.',BT('Add course','ext-new-course','plus','primary'))+
    U.toolbar('courses','Search courses, subjects, or levels…',B(`${P.courses.filter(c=>c.status==='Active').length} active courses`,'success'))+`<div class="grid-three" id="courses-rows">${courseCards()}</div>`;
  Z.renderers[R.COURSE]=()=>{const c=Z.selectedCourse(),groups=P.groups.filter(g=>g.course===c.id);return Z.heading(E(c.name),'Courses / Course details',BT('Back to courses','go:'+R.COURSES,'left')+BT('Create group','ext-new-group','plus','primary'))+
    `<section class="panel detail-hero"><span class="course-symbol">${I(c.icon)}</span><div class="grow"><div class="row"><h2>${E(c.name)}</h2>${U.status(c.status)}</div><p>${E(c.description)}</p></div></section><div class="detail-layout"><div class="detail-main">${U.panel('Course overview',`<div class="course-facts" style="border:0;padding:0"><div class="mini-stat"><strong>${c.months} months</strong><span>Course duration</span></div><div class="mini-stat"><strong>${c.lessons} lessons</strong><span>Per month</span></div><div class="mini-stat"><strong>${c.minutes} min</strong><span>Lesson length</span></div></div>`)}<div style="height:18px"></div>${U.table([['Group',21],['Teacher',30],['Schedule',31],['Seats',18]],groups.map(g=>`<tr><td>${U.link(g.name,'ext-open-group:'+g.id)}<p class="table-secondary">${g.branch}</p></td><td>${A(g.teacher,'','small')} <span class="caption">${g.teacher.split(' ')[0]} ${g.teacher.split(' ')[1][0]}.</span></td><td><span class="table-primary">${g.days}</span><p class="table-secondary mono">${g.time}</p></td><td class="mono">${g.enrolled}/${g.capacity}</td></tr>`).join(''),'','<span>Groups following this course</span>')}<div style="height:18px"></div>${U.panel('Learning journey',`<div class="course-outline">${['Build a strong foundation','Practice in real situations','Apply, assess, and progress'].map((t,i)=>`<div class="outline-item"><span class="outline-number">0${i+1}</span><div><h3>${t}</h3><p>Guided lessons, structured practice, and teacher feedback.</p></div></div>`).join('')}</div>`)}</div><aside class="detail-aside">${U.panel('Standard tuition',`<div class="balance-value mono text-primary" style="font-size:27px">${M(c.price)}<small>UZS / month</small></div><p class="caption">Base fee before group or student adjustments.</p><div class="balance-rule"></div><div class="detail-pairs"><div class="detail-row"><span>Subject</span><strong>${E(c.subject)}</strong></div><div class="detail-row"><span>Level</span><strong>${E(c.level)}</strong></div><div class="detail-row"><span>Total planned lessons</span><strong>${c.months*c.lessons}</strong></div></div>`)}${U.panel('Enrollment overview',U.bars([['Enrolled students',c.students+'',Math.min(c.students,90)],['Running groups',groups.length+'',groups.length*20]]))}</aside></div>`;};
  const groupRows=()=>P.groups.filter(g=>U.match('groups',g.name,Z.courseName(g.course),g.teacher,g.branch)&&(P.groupFilter===undefined||P.groupFilter==='all'||g.status===P.groupFilter)).map(g=>`<tr><td>${U.link(g.name,'ext-open-group:'+g.id)}<p class="table-secondary">${E(Z.courseName(g.course))}</p></td><td><span class="row">${A(g.teacher,'','small')}<span>${g.teacher.split(' ')[0]} ${g.teacher.split(' ')[1][0]}.</span></span></td><td><div class="table-primary">${g.days}</div><p class="table-secondary mono">${g.time}</p></td><td><div class="table-primary">${g.branch}</div><p class="table-secondary">Room ${g.room}</p></td><td><div class="capacity mono">${g.enrolled} / ${g.capacity}<div class="capacity-track"><span style="width:${g.enrolled/g.capacity*100}%"></span></div></div></td><td>${U.status(g.status)}</td><td class="mono">${M(g.price)}</td></tr>`).join('');
  Z.listRenderers.groups=groupRows;
  Z.renderers[R.GROUPS]=()=>Z.heading('Groups','Keep every cohort organized, from enrollment to graduation.',BT('Create group','ext-new-group','plus','primary'))+
    U.metrics([['Total groups',P.groups.length,'Across both academy branches','group'],['Active',P.groups.filter(g=>g.status==='Active').length,'Classes currently in progress','checkCircle','success'],['Recruiting',P.groups.filter(g=>g.status==='Recruiting').length,'Open for student enrollment','users'],['Available seats',P.groups.reduce((a,g)=>a+g.capacity-g.enrolled,0),'Across current groups','calendar']])+
    U.toolbar('groups','Search group, course, or teacher…',`<select class="select" data-extra-filter="group-status" aria-label="Group status"><option value="all">All statuses</option>${['Active','Recruiting'].map(v=>`<option ${P.groupFilter===v?'selected':''}>${v}</option>`).join('')}</select>`)+U.table([['Group / course',22],['Teacher',17],['Schedule',20],['Branch / room',15],['Seats',9],['Status',10],['Fee, UZS',12]],groupRows(),'groups','<span>Capacity and enrollment across the current teaching term</span>');
  Z.renderers[R.GROUP]=()=>{const g=Z.selectedGroup(),c=P.courses.find(c=>c.id===g.course)||P.courses[0];const students=P.students.filter(s=>s.group===g.name);let body='';
    if(P.groupTab==='students')body=U.table([['Student',35],['Phone',25],['Status',18],['Balance, UZS',22]],students.map(s=>`<tr><td><div class="row gap-12">${A(s.name)}<div>${U.link(s.name,'ext-open-student:'+s.id)}<p class="table-secondary">#${s.code}</p></div></div></td><td class="caption mono">${s.phone}</td><td>${U.status(s.status)}</td><td class="mono ${Z.studentBalance(s)<0?'text-danger':'text-success'}">${Z.signedMoney(Z.studentBalance(s))}</td></tr>`).join(''),'','<span>Sample enrolled students · '+g.enrolled+' total enrollments</span>');
    if(P.groupTab==='lessons')body=U.table(['Lesson','Date','Time','Topic','Status'],[['12','2 Nov','09:00–10:30','Speaking & fluency','Completed'],['13','4 Nov','09:00–10:30','Listening strategies','Scheduled'],['14','6 Nov','09:00–10:30','Writing practice','Scheduled'],['15','9 Nov','09:00–10:30','Reading techniques','Scheduled']].map(d=>`<tr>${d.slice(0,4).map(x=>`<td>${x}</td>`).join('')}<td>${U.status(d[4])}</td></tr>`).join(''));
    if(P.groupTab==='billing')body=U.panel('Billing policy',`<div class="detail-pairs"><div class="detail-row"><span>Billing model</span><strong>${g.billing}</strong></div><div class="detail-row"><span>Monthly base fee</span><strong class="mono">${M(g.price,true)}</strong></div><div class="detail-row"><span>Course duration</span><strong>${c.months} months</strong></div><div class="detail-row"><span>Trial students</span><strong>Not charged</strong></div><div class="detail-row"><span>Student-level adjustments</span><strong>Applied individually</strong></div></div><div class="profile-callout">${I('shield')}Billing follows each student’s active enrollment and group policy.</div>`);
    return Z.heading(E(c.name)+' · '+E(g.name),'Groups / Group details',BT('All groups','go:'+R.GROUPS,'left')+BT('Attendance','go:'+R.ATTENDANCE,'book')+BT('Add student','ext-group-enroll','plus','primary'))+
    `<section class="panel detail-hero"><span class="course-symbol">${I('group')}</span><div class="grow"><div class="row"><h2>${E(g.name)}</h2>${U.status(g.status)}</div><p>${E(c.name)} · ${g.branch} · Room ${g.room}</p></div><div class="detail-hero-facts"><div class="mini-stat"><span>Teacher</span><strong>${g.teacher.split(' ')[0]} ${g.teacher.split(' ')[1][0]}.</strong></div><div class="mini-stat"><span>Class time</span><strong class="mono">${g.time}</strong></div><div class="mini-stat"><span>Enrollment</span><strong>${g.enrolled} / ${g.capacity}</strong></div></div></section><div class="detail-layout"><div class="detail-main">${U.tabs([['students','Students',g.enrolled],['lessons','Lesson schedule'],['billing','Billing policy']],P.groupTab,'ext-group-tab')}${body}</div><aside class="detail-aside">${U.panel('Group details',`<div class="detail-pairs"><div class="detail-row"><span>Schedule</span><strong>${g.days}</strong></div><div class="detail-row"><span>Start date</span><strong>12 August, 2026</strong></div><div class="detail-row"><span>Lesson length</span><strong>${c.minutes} minutes</strong></div><div class="detail-row"><span>Room capacity</span><strong>${g.capacity} seats</strong></div><div class="detail-row"><span>Tuition</span><strong>${M(g.price,true)}</strong></div><div class="detail-row"><span>Billing</span><strong>${g.billing}</strong></div></div>`)}${U.panel('Teaching team',`<div class="row gap-12">${A(g.teacher)}<div><h3>${g.teacher}</h3><p class="caption">Lead teacher</p></div></div><div style="height:15px"></div>${BT('View staff','go:'+R.STAFF,'users','wide')}`)}</aside></div>`;};
  const branchCards=()=>P.branches.map(b=>`<button type="button" class="branch-card ${P.selectedBranch===b.id?'selected':''}" data-action="ext-select-branch:${b.id}"><header><span class="course-symbol">${I('building')}</span><div class="grow"><h2>${E(b.name)}</h2><p>${b.main?'Main branch':'Academy branch'}</p></div>${U.status(b.status)}</header><p class="row">${I('pin')}${E(b.address)}</p><p class="row">${I('phone')}${E(b.phone)}</p><div class="branch-stats"><div><strong>${P.rooms.filter(r=>r.branch===b.id).length}</strong><span>Classrooms</span></div><div><strong>${P.groups.filter(g=>g.branch===b.name).length}</strong><span>Groups</span></div><div><strong>${P.rooms.filter(r=>r.branch===b.id).reduce((a,r)=>a+r.capacity,0)}</strong><span>Total seats</span></div></div></button>`).join('');
  Z.renderers[R.BRANCHES]=()=>Z.heading('Branches & classrooms','Give every class a place to thrive.',BT('Add branch','ext-new-branch','building')+BT('Add classroom','ext-new-room','plus','primary'))+
    `<div class="equal-panels">${branchCards()}</div><div class="row between" style="margin:22px 0 14px"><div><h2>Classrooms · ${E(P.branches.find(b=>b.id===P.selectedBranch)?.name||'Yunusobod')}</h2><p class="caption">Room capacity helps avoid overcrowded classes.</p></div>${BT('Open timetable','go:'+R.SCHEDULE,'calendar','small')}</div>`+
    U.table([['Room',24],['Type',25],['Capacity',17],['Current groups',18],['Status',16]],P.rooms.filter(r=>r.branch===P.selectedBranch).map(r=>`<tr><td><span class="room-type">${I(r.type==='Computer lab'?'panel':'building')}<strong class="table-primary">${E(r.name)}</strong></span></td><td>${E(r.type)}</td><td>${r.capacity} students</td><td>${P.groups.filter(g=>g.room===r.name&&g.branch===P.branches.find(b=>b.id===r.branch)?.name).length} groups</td><td>${U.status(r.status)}</td></tr>`).join(''));
})();
